custom_css:
/* ══════════════════════════════════
   美化框架模板-丹凤
   ══════════════════════════════════ */

/* ── 字体引入 ── */
@font-face{
font-family:"RetroStampSong";
src:url("./css/子曰温故而知新.ttf") format("truetype");
}
*{font-family:"RetroStampSong",sans-serif;}
/* ══════════════════════════════════
   📱 移动端变量
   ══════════════════════════════════ */
:root{
--手机头像宽度:160px;
--手机头像高度:200px;
--手机头像左偏移:8px;
--手机头像上偏移:-196px;
--手机首条气泡上方留白:205px;
--手机气泡之间留白:215px;
--手机角色名左偏移:230px;
--手机角色名上偏移:-150px;
--手机角色名字号:calc(var(--mainFontSize)*1);
--手机时间戳左偏移:230px;
--手机时间戳上偏移:0px;
--手机消息ID左偏移:250px;
--手机消息ID上偏移:-120px;
--手机Token计数左偏移:250px;
--手机Token计数上偏移:-100px;
--手机计时器左偏移:250px;
--手机计时器上偏移:-80px;
}
/* ══════════════════════════════════
   :root 变量总表
   ══════════════════════════════════ */
:root{
/* ─ 字体链接/定义 ─ */
--mainFontFamily:"RetroStampSong","Noto Serif SC",serif;
--主字体:"Noto Serif SC",serif;
--行高:1.8em;
/* 基准字号由ST的font_scale控制,
   下方所有字号均用calc(var(--mainFontSize)*倍率)
   --mainFontSize由ST自动生成 */

/* ─ 头像 ─ */
--头像宽度:160px;
--头像高度:222px;
--头像左偏移:10px;
--头像上偏移:-254px;
--头像圆角:0px;
--头像图片圆角:0px;
--头像裁剪位置:center 25%;
--头像边框粗细:4px;
--头像边框颜色:var(--边框颜色);
--头像边框样式:solid;
--头像阴影:0 0 12px rgba(200,195,235,0.18);

/* ─ 三元素：角色名·时间戳·标签 ─ */
--角色名左偏移:180px;
--角色名上偏移:-254px;
--角色名字号:calc(var(--mainFontSize)*0.94);
--角色名颜色:var(--主文字颜色);
--角色名字间距:2px;
--角色名下划线颜色:var(--次要文字颜色);
--角色名下划线粗细:1px;
--角色名下方留白:6px;
--角色名前缀字号:calc(var(--mainFontSize)*0.56);
--时间戳左偏移:188px;
--时间戳上偏移:-222px;
--时间戳字号:calc(var(--mainFontSize)*0.69);
--时间戳颜色:var(--次要文字颜色);
--消息ID左偏移:188px;
--消息ID上偏移:-214px;
--消息ID颜色:var(--次要文字颜色);
--消息ID字号:calc(var(--mainFontSize)*0.69);
--Token计数左偏移:188px;
--Token计数上偏移:-190px;
--Token计数颜色:var(--次要文字颜色);
--计时器左偏移:188px;
--计时器上偏移:-164px;
--计时器颜色:var(--次要文字颜色);

/* ─ 操作按钮 ─ */
--操作按钮上偏移:-200px;
--操作按钮右偏移:10px;
--操作按钮字号:calc(var(--mainFontSize)*0.75);
--操作按钮颜色:var(--次要文字颜色);

/* ─ 气泡相关 ─ */
--气泡边框粗细:0px;
--气泡边框样式:solid;
--气泡边框颜色:var(--边框颜色);
--气泡圆角:0px;
--气泡阴影:0 0 24px rgba(112,115,173,0.06);
--首条气泡上方留白:275px;
--气泡之间留白:285px;
--气泡内边距上:30px;
--气泡内边距右:20px;
--气泡内边距下:25px;
--气泡内边距左:20px;
--文字区内边距上:5px;
--文字区内边距右:5px;
--文字区内边距下:10px;
--文字区内边距左:5px;
--选中气泡左边框粗细:3px;

/* ─ 消息块布局 ─ */
--消息块宽度:100vw;
--消息块下内边距:30px;
--消息文字区内边距:10px;
--聊天区底部留白:100px;

/* ─ 颜色系统（映射ST面板） ─ */
--主文字颜色:var(--SmartThemeBodyColor);
--斜体文字颜色:var(--SmartThemeEmColor);
--引用文字颜色:var(--SmartThemeQuoteColor);
--强调色:var(--SmartThemeQuoteColor);
--强调色2:var(--SmartThemeUnderlineColor);
--页面背景色:var(--SmartThemeChatTintColor);
--UI背景色:var(--SmartThemeBlurTintColor);
--边框颜色:var(--SmartThemeBorderColor);
--角色气泡背景色:var(--SmartThemeBotMesBlurTintColor);
--用户气泡背景色:var(--SmartThemeUserMesBlurTintColor);
--代码块背景色:var(--SmartThemeShadowColor);
--次要文字颜色:color-mix(in srgb,var(--主文字颜色) 45%,transparent);

/* ─ 文本类型样式 ─ */
--斜体背景色:color-mix(in srgb,var(--强调色) 12%,transparent);
--斜体左边框色:var(--强调色);
--斜体左边框粗细:2px;
--斜体内边距:3px 6px;
--斜体圆角:0;
--引用块背景色:color-mix(in srgb,var(--UI背景色) 80%,var(--主文字颜色));
--引用块左边框色:var(--强调色);
--引用块左边框粗细:3px;
--引用块内边距:14px 16px;
--引用块圆角:0px;
--引用块外边距:8px 0;
--引用块段落间距:3px 0;
--代码块边框色:color-mix(in srgb,var(--UI背景色) 60%,var(--主文字颜色));
--代码块文字色:var(--主文字颜色);
--代码块内边距:8px;
--代码块圆角:0;
--行内代码内边距:1px 4px;
--行内代码圆角:0;

/* ─ 装饰开关 1=显示 0=隐藏 ─ */
--显示角色名前缀符号:1;

/* ─ 顶栏 ─ */
--顶栏图标透明度:1;
--顶栏图标字号:calc(var(--mainFontSize)*1.3);
--顶栏图标颜色:var(--apricot);

/* ─ 滚动条 ─ */
--滚动条宽度:6px;
--滚动条圆角:10px;
--滚动条颜色:var(--强调色);

/* ─ 思维链 ─ */
--思维链内容:'[思维链]';
--思维链上偏移: 0px;
--思维链左偏移: 0px;
--思维链宽度:100%;
--思维链标签字号:calc(var(--mainFontSize)*0.75);
--思维链标签颜色:var(--ink);
--思维链内边距:5px 8px;
--思维链箭头大小:12px;
--思维链箭头右偏移:-20px;

/* ─ 发送按钮 ─ */
--发送按钮左间距:10px;

/* ─ 安全区域 ─ */
--安全区域底部基础留白:8px;

/* ─ 媒体查询断点 ─ */
/* --移动端断点:768px (媒体查询不支持var,仅做记录) */

/* ─ 预设页面 ─ */
--预设页面内边距:1.2em 0.75em 0.5em 0.5em;

/* ─ 提示词管理器 ─ */
--提示词管理器头部背景:#C8C8C8;
--提示词管理器头部文字:#000;
}



/* ══════════════════════════════════
   ↓ 框架代码 一般不用动 ↓
   ══════════════════════════════════ */

/* ── 思维链 ── */
.mes_reasoning,
.mes_reasoning_summary{width:var(--思维链宽度)!important;}
.mes_reasoning_header{
background:transparent;
border:none;border-radius:0;
padding:var(--思维链内边距);
margin-top:var(--思维链上偏移);
margin-left:var(--思维链左偏移);
}
.mes_reasoning_actions{
margin-top:var(--思维链上偏移);
margin-left:var(--思维链左偏移);
}
.mes_reasoning_header_title{font-size:0!important;}
.mes_reasoning_header_title::before{
content:var(--思维链内容);
font-size:var(--思维链标签字号);
color:var(--思维链标签颜色);
}
.mes_reasoning_arrow{font-size:var(--思维链箭头大小)!important;margin-right:var(--思维链箭头右偏移);}

/* ── 顶栏 ── */
#top-settings-holder,
#top-bar,
.header-container,
.nav-bar{
box-shadow:none!important;
-webkit-box-shadow:none!important;
}
#top-settings-holder .drawer .drawer-icon{
opacity:var(--顶栏图标透明度);
font-size:var(--顶栏图标字号);
text-shadow:none!important;
color:var(--顶栏图标颜色);
}

/* ── 去灰色背景 ── */
h4,.standoutHeader{
background-image:none!important;
background-color:transparent;
}
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block{
background-image:none!important;
}

/* ── 全局控件 ── */
.text_pole,
.range-block-counter input,
input,select,textarea,
.reasoning_edit_textarea,
.edit_textarea{background-color:transparent;}
.neo-range-input{background-color:transparent;}
select option{
color:black!important;
background:transparent!important;
}
.select2-container .select2-selection--multiple,
.select2-container .select2-selection--single{
color:black!important;
background:transparent!important;
}
.select2_choice_clickable_buttonstyle+span.select2-container .select2-selection__choice__display{
color:black!important;
background:transparent!important;
}
.standoutHeader~.inline-drawer-content{background:transparent!important;}
.reverse_proxy_warning{background:transparent!important;}

/* ── 预设页面 ── */
.fillLeft .scrollableInner{padding:var(--预设页面内边距);}
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled){
background-color:var(--页面背景色);
}
.completion_prompt_manager_prompt a{color:var(--主文字颜色)!important;}
.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled{
background-color:var(--页面背景色);
}
.completion_prompt_manager_prompt_disabled a{color:var(--次要文字颜色)!important;}

/* ── 取消全局滤镜 ── */
html,body,*{
filter:none!important;
-webkit-filter:none!important;
}

/* ── 字体应用 ── */
body{font-family:var(--主字体);}

/* ══════ 聊天区域 ══════ */
#chat,
#chat>div,
.chat-scroll-container,
.chat-messages-container{
border:none!important;
background-color:var(--页面背景色)!important;
}
#chat{padding:0!important;padding-bottom:var(--聊天区底部留白)!important;}

/* ══════ 气泡主体 ══════ */
.mes{
position:relative;
overflow:visible;
background-color:transparent;
}
.mes+.mes{margin-top:var(--气泡之间留白);}
.mes[is_user="true"]{background-color:var(--用户气泡背景色);}
.mes.selected{border-left:var(--选中气泡左边框粗细) solid var(--强调色)!important;}

/* ══════ 头像 ══════ */
.mesAvatarWrapper .avatar{
position:absolute!important;
top:var(--头像上偏移)!important;
left:var(--头像左偏移)!important;
width:var(--头像宽度)!important;
height:var(--头像高度)!important;
border-radius:var(--头像圆角)!important;
border:var(--头像边框粗细) var(--头像边框样式) var(--头像边框颜色)!important;
box-shadow:var(--头像阴影)!important;
overflow:hidden;
}
.mesAvatarWrapper{position:relative;}
.mesAvatarWrapper::after{
content:"";
position:absolute;
top:var(--头像上偏移);
left:var(--头像左偏移);
width:var(--头像宽度);
height:var(--头像高度);
background-repeat:no-repeat;
pointer-events:none;
z-index:5;
border-radius:var(--头像圆角);
}
#chat .mes .avatar img{
width:100%;height:100%;
object-fit:cover;
object-position:var(--头像裁剪位置);
border-radius:var(--头像图片圆角)!important;
border:none!important;
outline:none!important;
}

/* ══════ 角色名 ══════ */
.mes .name_text{
position:absolute!important;
left:var(--角色名左偏移)!important;
top:var(--角色名上偏移)!important;
bottom:auto!important;right:auto!important;
transform:none!important;margin:0!important;
writing-mode:horizontal-tb;
white-space:nowrap;
font-size:var(--角色名字号);
color:var(--角色名颜色);
letter-spacing:var(--角色名字间距);
z-index:10;pointer-events:none;
border-bottom:var(--角色名下划线粗细) solid var(--角色名下划线颜色);
padding-bottom:var(--角色名下方留白);
}
.mes .name_text::before{
content:"◆ ";
font-size:var(--角色名前缀字号);
color:var(--次要文字颜色);
vertical-align:middle;
scale:var(--显示角色名前缀符号);
display:inline-block;
}
.mes .name_text::after{
content:" ◆";
font-size:var(--角色名前缀字号);
color:var(--次要文字颜色);
vertical-align:middle;
scale:var(--显示角色名前缀符号);
display:inline-block;
}

/* ══════ 时间戳 ══════ */
.mes small.timestamp{
position:absolute!important;
left:var(--时间戳左偏移)!important;
top:var(--时间戳上偏移)!important;
bottom:auto!important;
transform:none!important;
font-size:var(--时间戳字号)!important;
color:var(--时间戳颜色)!important;
opacity:1!important;
white-space:nowrap;
z-index:10;pointer-events:none;
}

/* ══════ 消息ID·Token计数·计时器 ══════ */
.mesIDDisplay,
.tokenCounterDisplay,
.mes_timer{
font-size:var(--消息ID字号)!important;
position:absolute;
display:inline-block;
}
.mesIDDisplay{
color:var(--消息ID颜色)!important;
top:var(--消息ID上偏移)!important;
left:var(--消息ID左偏移)!important;
right:auto!important;
}
.tokenCounterDisplay{
color:var(--Token计数颜色)!important;
top:var(--Token计数上偏移)!important;
left:var(--Token计数左偏移)!important;
right:auto!important;
}
.mes_timer{
color:var(--计时器颜色)!important;
top:var(--计时器上偏移)!important;
left:var(--计时器左偏移)!important;
right:auto!important;
}

/* ══════ 文字容器 ══════ */
.mes .mes_text{
margin:0 auto!important;
padding:var(--文字区内边距上) var(--文字区内边距右) var(--文字区内边距下) var(--文字区内边距左)!important;
position:relative;z-index:3;
}
.mes_text{line-height:var(--行高);}

/* ══════ 文字样式 ══════ */
p,strong{color:var(--主文字颜色)!important;}
em{
background:var(--斜体背景色);
border:none;
border-left:var(--斜体左边框粗细) solid var(--斜体左边框色);
border-radius:var(--斜体圆角);
padding:var(--斜体内边距);
color:var(--斜体文字颜色);
font-style:italic;
}
pre{
background:var(--代码块背景色)!important;
color:var(--代码块文字色)!important;
border:1px solid var(--代码块边框色)!important;
padding:var(--代码块内边距)!important;
box-shadow:none!important;
}
code{
background-color:var(--代码块背景色)!important;
border:1px solid var(--代码块边框色)!important;
color:var(--代码块文字色)!important;
padding:var(--行内代码内边距);
border-radius:var(--行内代码圆角);
}

/* ── 引用块 ── */
.mes_text blockquote,
.markdown-blockquote,
blockquote{
position:relative;
background:var(--引用块背景色);
border:none;
border-left:var(--引用块左边框粗细) solid var(--引用块左边框色);
border-radius:var(--引用块圆角);
padding:var(--引用块内边距);
margin:var(--引用块外边距);
color:var(--引用文字颜色);
box-shadow:none;
}
blockquote p{
margin:var(--引用块段落间距)!important;
line-height:var(--行高);
}

/* ══════ 操作按钮 ══════ */
.mes_buttons i{color:var(--操作按钮颜色)!important;}
.mes .mes_buttons{
position:absolute!important;
top:var(--操作按钮上偏移)!important;
right:var(--操作按钮右偏移)!important;
opacity:1;transition:opacity 0.2s;z-index:10;
}
.mes_buttons,
.extraMesButtons{font-size:var(--操作按钮字号)!important;}

/* ══════ 滚动条 ══════ */
::-webkit-scrollbar{
width:var(--滚动条宽度);
height:var(--滚动条宽度);
background:transparent;
}
::-webkit-scrollbar-track{background:transparent;}
::-webkit-scrollbar-thumb{
background:color-mix(in srgb,var(--滚动条颜色) 0%,transparent);
border-radius:var(--滚动条圆角);
transition:background 0.3s ease;
}
*:hover::-webkit-scrollbar-thumb{
background:color-mix(in srgb,var(--滚动条颜色) 35%,transparent);
}
*:hover::-webkit-scrollbar-thumb:hover{
background:color-mix(in srgb,var(--滚动条颜色) 55%,transparent);
}
*{scrollbar-width:thin;scrollbar-color:transparent transparent;}
*:hover{
scrollbar-color:color-mix(in srgb,var(--滚动条颜色) 35%,transparent) transparent;
}

/* ══════ 消息块布局 ══════ */
.mes,.mes_block{
width:var(--消息块宽度)!important;
max-width:var(--消息块宽度)!important;
margin-left:0!important;
margin-right:0!important;
box-sizing:border-box!important;
}
.mes_block{padding:0 0 var(--消息块下内边距) 0!important;}
.mes_text{
margin:0;
padding:var(--消息文字区内边距);
line-height:var(--行高);
}

/* ── 发送按钮 ── */
#send_but{margin-left:var(--发送按钮左间距)!important;}

/* ── QR栏悬停显隐 ── */
#qr--bar{
height:0;overflow:hidden;opacity:0;
transition:height 0.4s ease,opacity 0.3s ease;
pointer-events:none;
}
#send_form:hover #qr--bar,
#qr--bar:hover{
height:auto;opacity:1;pointer-events:auto;
}

/* ── 提示词管理器头部 ── */
.completion_prompt_manager_header{
background-color:var(--提示词管理器头部背景);
color:var(--提示词管理器头部文字)!important;
}

/* ══════ 移动端适配 ══════ */
@media screen and (max-width:768px){
.mes{margin-top:var(--手机首条气泡上方留白);}
.mes+.mes{margin-top:var(--手机气泡之间留白);}
.mesAvatarWrapper .avatar{
top:var(--手机头像上偏移)!important;
left:var(--手机头像左偏移)!important;
width:var(--手机头像宽度)!important;
height:var(--手机头像高度)!important;
}
.mesAvatarWrapper::after{
top:var(--手机头像上偏移);
left:var(--手机头像左偏移);
width:var(--手机头像宽度);
height:var(--手机头像高度);
}
.mes .name_text{
left:var(--手机角色名左偏移)!important;
top:var(--手机角色名上偏移)!important;
font-size:var(--手机角色名字号);
}
.mes small.timestamp{
left:var(--手机时间戳左偏移)!important;
top:var(--手机时间戳上偏移)!important;
}
.mesIDDisplay{
top:var(--手机消息ID上偏移)!important;
left:var(--手机消息ID左偏移)!important;
}
.tokenCounterDisplay{
top:var(--手机Token计数上偏移)!important;
left:var(--手机Token计数左偏移)!important;
}
.mes_timer{
top:var(--手机计时器上偏移)!important;
left:var(--手机计时器左偏移)!important;
}


